// AUTO-GENERATED from "Residential Property Sale Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms under which Seventh Sky will provide Residential Property Sale Services to assist the Client in preparing, marketing, promoting, negotiating and coordinating the sale of the property.</p><p style=\"margin:6px 0;\">The Agreement establishes the rights and responsibilities of both Parties in relation to property preparation, marketing, buyer management, negotiations, documentation coordination, settlement support and other agreed sale services.</p><p style=\"margin:6px 0;\">The specific services, pricing and engagement scope applicable to each property will be confirmed in the approved Quotation, Work Order or Property Sale Schedule.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the property sale is completed;</li><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">the Agreement is terminated in accordance with this Agreement; or</li><li style=\"margin:2px 0;\">both Parties otherwise agree in writing.</li></ul><p style=\"margin:6px 0;\">Where the Client engages Seventh Sky on an exclusive basis, the exclusive engagement period shall be specified in the approved Quotation or Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">Depending on the selected engagement, Seventh Sky may provide one or more of the following services.</p><p style=\"margin:6px 0;\">Only the services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Assessment &amp; Sales Strategy</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Property Consultation</li><li style=\"margin:2px 0;\">☐ Property Assessment</li><li style=\"margin:2px 0;\">☐ Market Appraisal</li><li style=\"margin:2px 0;\">☐ Pricing Strategy</li><li style=\"margin:2px 0;\">☐ Sales Strategy</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Preparation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Cleaning Coordination</li><li style=\"margin:2px 0;\">☐ Gardening &amp; Landscaping Coordination</li><li style=\"margin:2px 0;\">☐ Repair &amp; Maintenance Coordination</li><li style=\"margin:2px 0;\">☐ Painting Coordination</li><li style=\"margin:2px 0;\">☐ Renovation Coordination</li><li style=\"margin:2px 0;\">☐ Property Styling</li><li style=\"margin:2px 0;\">☐ Furniture &amp; Home Presentation</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Marketing &amp; Promotion</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Professional Photography</li><li style=\"margin:2px 0;\">☐ Drone Photography &amp; Videography</li><li style=\"margin:2px 0;\">☐ Property Listing Preparation</li><li style=\"margin:2px 0;\">☐ Online Marketing</li><li style=\"margin:2px 0;\">☐ Social Media Promotion</li><li style=\"margin:2px 0;\">☐ Advertising Campaigns</li><li style=\"margin:2px 0;\">☐ Brochure Preparation</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Buyer Management</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Buyer Enquiry Management</li><li style=\"margin:2px 0;\">☐ Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Open House Coordination</li><li style=\"margin:2px 0;\">☐ Buyer Follow-up</li><li style=\"margin:2px 0;\">☐ Buyer Feedback Reports</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Negotiation &amp; Transaction Support</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Offer Coordination</li><li style=\"margin:2px 0;\">☐ Negotiation Support</li><li style=\"margin:2px 0;\">☐ Sale Agreement Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li><li style=\"margin:2px 0;\">☐ Handover Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Documentation &amp; Professional Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Ownership Verification Coordination</li><li style=\"margin:2px 0;\">☐ Conveyancing Coordination</li><li style=\"margin:2px 0;\">☐ Legal Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Property Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Financial Institution Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Utility Disconnection Coordination</li><li style=\"margin:2px 0;\">☐ Property Cleaning Before Handover</li><li style=\"margin:2px 0;\">☐ Property Maintenance Prior to Settlement</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional services may be included by written agreement.</p>"],
  ["PROPERTY DETAILS", "<p style=\"margin:6px 0;\">The property details shall be recorded in Schedule B or the approved Property Sale Schedule.</p><p style=\"margin:6px 0;\">The information may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Property Address;</li><li style=\"margin:2px 0;\">Property Type;</li><li style=\"margin:2px 0;\">Ownership Status;</li><li style=\"margin:2px 0;\">Title Reference (if applicable);</li><li style=\"margin:2px 0;\">Estimated Market Value;</li><li style=\"margin:2px 0;\">Agreed Listing Price;</li><li style=\"margin:2px 0;\">Minimum Acceptable Sale Price (if agreed);</li><li style=\"margin:2px 0;\">Existing Mortgage Details (if disclosed);</li><li style=\"margin:2px 0;\">Existing Tenancy (if applicable);</li><li style=\"margin:2px 0;\">Special Conditions; and</li><li style=\"margin:2px 0;\">Selected Services.</li></ul><p style=\"margin:6px 0;\">Where any inconsistency exists between this Agreement and the approved Work Order or Property Sale Schedule, the approved Work Order or Property Sale Schedule shall prevail for that transaction.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Client agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate ownership and property information;</li><li style=\"margin:2px 0;\">confirm that they have legal authority to sell the property;</li><li style=\"margin:2px 0;\">provide all documents reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">disclose any mortgages, caveats, legal proceedings, succession issues, ownership disputes or restrictions affecting the property;</li><li style=\"margin:2px 0;\">cooperate with inspections, buyer enquiries and reasonable marketing activities;</li><li style=\"margin:2px 0;\">provide reasonable access to the property;</li><li style=\"margin:2px 0;\">promptly notify Seventh Sky of any material changes affecting the property or sale;</li><li style=\"margin:2px 0;\">pay all agreed fees and approved third-party expenses in accordance with this Agreement;</li><li style=\"margin:2px 0;\">obtain independent legal, taxation and financial advice where appropriate; and</li><li style=\"margin:2px 0;\">act honestly and in good faith throughout the sale process.</li></ul><p style=\"margin:6px 0;\">The Client acknowledges that they remain responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the accuracy of all ownership documents;</li><li style=\"margin:2px 0;\">legal ownership of the property;</li><li style=\"margin:2px 0;\">taxation obligations arising from the sale;</li><li style=\"margin:2px 0;\">settlement obligations owed by the Seller; and</li><li style=\"margin:2px 0;\">compliance with all applicable laws.</li></ul>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide the agreed Services with reasonable care and skill;</li><li style=\"margin:2px 0;\">coordinate the agreed marketing activities;</li><li style=\"margin:2px 0;\">communicate with prospective buyers;</li><li style=\"margin:2px 0;\">coordinate inspections and buyer enquiries;</li><li style=\"margin:2px 0;\">assist with negotiations where authorised;</li><li style=\"margin:2px 0;\">coordinate with lawyers, conveyancers, valuers, banks and other approved professionals where required;</li><li style=\"margin:2px 0;\">keep the Client reasonably informed of significant developments;</li><li style=\"margin:2px 0;\">provide progress updates throughout the sale process; and</li><li style=\"margin:2px 0;\">coordinate settlement activities where included within the agreed Services.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts as the Property Sale Coordinator and Service Provider and does not act as the legal owner, conveyancer, solicitor, valuer or financial adviser.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before commencing the Services, Seventh Sky may issue a Quotation or Work Order specifying:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services;</li><li style=\"margin:2px 0;\">engagement type (exclusive or non-exclusive);</li><li style=\"margin:2px 0;\">professional fees;</li><li style=\"margin:2px 0;\">commission (if applicable);</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected project timeframe; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Additional services requested after commencement may require a revised Quotation, Work Order or approved variation before work proceeds.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The fees payable under this Agreement shall be specified in the approved Quotation, Work Order or Property Sale Schedule.</p><p style=\"margin:6px 0;\">Depending on the selected services, fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">consultation fees;</li><li style=\"margin:2px 0;\">property assessment;</li><li style=\"margin:2px 0;\">market appraisal;</li><li style=\"margin:2px 0;\">property preparation coordination;</li><li style=\"margin:2px 0;\">marketing and advertising;</li><li style=\"margin:2px 0;\">buyer enquiry management;</li><li style=\"margin:2px 0;\">inspection coordination;</li><li style=\"margin:2px 0;\">negotiation support;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination;</li><li style=\"margin:2px 0;\">professional commission (where applicable);</li><li style=\"margin:2px 0;\">approved third-party service fees; and</li><li style=\"margin:2px 0;\">any other agreed services.</li></ul><p style=\"margin:6px 0;\">The Client agrees to pay all agreed fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government charges, legal fees, conveyancing fees, property valuation fees, bank fees, taxes, advertising costs and other approved third-party expenses remain the responsibility of the Client unless otherwise agreed in writing.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Sale Services</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Deposit upon acceptance of the Quotation or Work Order (where applicable).</li><li style=\"margin:2px 0;\">Progress payments for approved milestone services (if applicable).</li><li style=\"margin:2px 0;\">Final payment upon completion of the agreed Services or settlement of the property sale, whichever occurs first.</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Commission-Based Engagement</p><p style=\"margin:6px 0;\">Where the Parties agree to a commission-based engagement, the agreed commission shall become payable upon successful completion of the sale and settlement of the property.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension of the Services.</p>"],
  ["PROPERTY SALE SERVICES", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to market the property and identify suitable prospective buyers.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">buyer availability is subject to market conditions;</li><li style=\"margin:2px 0;\">property values may change over time;</li><li style=\"margin:2px 0;\">prospective buyers have the right to withdraw or amend offers;</li><li style=\"margin:2px 0;\">successful sale of the property cannot be guaranteed; and</li><li style=\"margin:2px 0;\">the final decision to accept or reject any offer remains with the Client.</li></ul><p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property marketing;</li><li style=\"margin:2px 0;\">buyer enquiries;</li><li style=\"margin:2px 0;\">private inspections;</li><li style=\"margin:2px 0;\">open house inspections;</li><li style=\"margin:2px 0;\">buyer feedback;</li><li style=\"margin:2px 0;\">offer negotiations;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination; and</li><li style=\"margin:2px 0;\">handover coordination.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project timeframes may be affected by:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">market conditions;</li><li style=\"margin:2px 0;\">buyer availability;</li><li style=\"margin:2px 0;\">Client instructions;</li><li style=\"margin:2px 0;\">property preparation requirements;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">finance approval;</li><li style=\"margin:2px 0;\">settlement arrangements;</li><li style=\"margin:2px 0;\">government processing;</li><li style=\"margin:2px 0;\">public holidays; or</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Client reasonably informed and provide an updated estimated timeframe where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">A variation occurs where the Client requests work outside the approved scope of Services or where additional work becomes necessary.</p><p style=\"margin:6px 0;\">Examples include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional advertising campaigns;</li><li style=\"margin:2px 0;\">additional photography or videography;</li><li style=\"margin:2px 0;\">property styling;</li><li style=\"margin:2px 0;\">renovation coordination;</li><li style=\"margin:2px 0;\">additional inspections;</li><li style=\"margin:2px 0;\">extended negotiations;</li><li style=\"margin:2px 0;\">valuation coordination;</li><li style=\"margin:2px 0;\">legal or conveyancing coordination;</li><li style=\"margin:2px 0;\">settlement extensions; or</li><li style=\"margin:2px 0;\">any other Client-requested services.</li></ul><p style=\"margin:6px 0;\">Where practical, Seventh Sky will advise the Client of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the additional work;</li><li style=\"margin:2px 0;\">any additional fees; and</li><li style=\"margin:2px 0;\">any expected impact on the project timeline.</li></ul><p style=\"margin:6px 0;\">No variation will proceed without the Client's approval unless immediate action is reasonably necessary to protect the Client's interests or facilitate the sale process.</p>"],
  ["BUYER COORDINATION & THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate inspections, negotiations and communication with prospective buyers and approved third-party professionals.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">buyer suitability is assessed only on information reasonably available at the relevant time;</li><li style=\"margin:2px 0;\">Seventh Sky does not guarantee a buyer's financial capacity, loan approval or completion of the purchase;</li><li style=\"margin:2px 0;\">lawyers, conveyancers, valuers, banks, financial institutions and other independent professionals remain responsible for their own advice and services;</li><li style=\"margin:2px 0;\">the Client remains responsible for deciding whether to accept an offer and proceed with the sale; and</li><li style=\"margin:2px 0;\">Seventh Sky remains responsible for coordinating the agreed Services with reasonable care and skill.</li></ul>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be considered completed when the agreed scope of work specified in the Quotation, Work Order or Property Sale Schedule has been substantially delivered.</p><p style=\"margin:6px 0;\">Depending on the selected services, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property assessment completed;</li><li style=\"margin:2px 0;\">property preparation coordinated;</li><li style=\"margin:2px 0;\">marketing campaign completed;</li><li style=\"margin:2px 0;\">buyer enquiries managed;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations coordinated;</li><li style=\"margin:2px 0;\">documentation coordinated;</li><li style=\"margin:2px 0;\">settlement completed;</li><li style=\"margin:2px 0;\">property handover coordinated; or</li><li style=\"margin:2px 0;\">any other agreed Services completed.</li></ul><p style=\"margin:6px 0;\">Where Seventh Sky is engaged for ongoing sales support, completion shall occur at the expiry of the agreed engagement period unless renewed by mutual agreement.</p>"],
  ["CLIENT COMPLAINTS & SERVICE ISSUES", "<p style=\"margin:6px 0;\">If the Client believes that the Services have not been delivered in accordance with the agreed scope, the Client should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">liaise with relevant parties where appropriate;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue;</li><li style=\"margin:2px 0;\">keep the Client informed of the outcome; and</li><li style=\"margin:2px 0;\">implement corrective action where reasonably appropriate.</li></ul><p style=\"margin:6px 0;\">Where the issue arises from Seventh Sky's administrative oversight, reasonable efforts will be made to rectify the matter promptly.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available to the Client under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">To the extent permitted by the laws of Bangladesh:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Seventh Sky will provide the agreed Services with reasonable care and skill.</li><li style=\"margin:2px 0;\">Seventh Sky is responsible only for the Services it has agreed to provide under this Agreement.</li><li style=\"margin:2px 0;\">The Client remains responsible for the legal ownership of the property and the accuracy of all ownership, financial and property information provided.</li><li style=\"margin:2px 0;\">The Client remains responsible for complying with all legal obligations relating to the sale of the property.</li><li style=\"margin:2px 0;\">Buyers remain responsible for their purchase decisions, finance arrangements and contractual obligations.</li><li style=\"margin:2px 0;\">Independent professionals, including lawyers, conveyancers, valuers, surveyors, banks, financial institutions and tax advisers, remain responsible for their own advice and services.</li><li style=\"margin:2px 0;\">Neither Party shall be liable for delays or failures resulting from circumstances beyond their reasonable control.</li></ul>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">Except where liability cannot legally be excluded or limited, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">a prospective buyer deciding not to proceed with the purchase;</li><li style=\"margin:2px 0;\">the Client deciding not to accept an offer;</li><li style=\"margin:2px 0;\">delays caused by finance approval, legal documentation, settlement processes or regulatory requirements;</li><li style=\"margin:2px 0;\">changes in market conditions or property values;</li><li style=\"margin:2px 0;\">inaccurate or incomplete information provided by the Client, buyers or third parties;</li><li style=\"margin:2px 0;\">the actions or omissions of buyers, contractors or independent professionals;</li><li style=\"margin:2px 0;\">loss of business opportunity, indirect loss, loss of profit or consequential loss arising from matters beyond Seventh Sky's reasonable control; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where permitted by law, Seventh Sky's total liability arising from the Services shall not exceed the amount paid by the Client for the affected Services.</p><p style=\"margin:6px 0;\">This clause does not exclude liability arising from fraud, wilful misconduct or any liability that cannot legally be excluded.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Each Party agrees to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Personal and property information will only be collected, used and disclosed for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the agreed Services;</li><li style=\"margin:2px 0;\">marketing and promoting the property for sale;</li><li style=\"margin:2px 0;\">communicating with the Client, prospective buyers and authorised representatives;</li><li style=\"margin:2px 0;\">coordinating with lawyers, conveyancers, valuers, banks and other authorised third parties;</li><li style=\"margin:2px 0;\">preparing quotations, Work Orders, inspection reports and invoices;</li><li style=\"margin:2px 0;\">complying with legal obligations; or</li><li style=\"margin:2px 0;\">other purposes authorised by the Client.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be responsible for delays or failure to perform caused by circumstances beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">severe weather;</li><li style=\"margin:2px 0;\">flood or fire;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">civil unrest;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">major technology failures;</li><li style=\"margin:2px 0;\">financial system disruptions; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["SELLER ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have reviewed and accepted the Quotation or Work Order before the Services commence;</li><li style=\"margin:2px 0;\">they are authorised to sell the property or act on behalf of the legal owner;</li><li style=\"margin:2px 0;\">they have provided accurate information regarding the property to the best of their knowledge;</li><li style=\"margin:2px 0;\">successful sale of the property depends on market conditions and buyer availability;</li><li style=\"margin:2px 0;\">the final decision to accept or reject any offer remains solely with the Client;</li><li style=\"margin:2px 0;\">independent legal, taxation and financial advice should be obtained before entering into a sale contract;</li><li style=\"margin:2px 0;\">some Services involve coordination with independent third-party professionals; and</li><li style=\"margin:2px 0;\">they have had the opportunity to ask questions and obtain independent professional advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend the Services where:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the Client fails to make payment in accordance with this Agreement;</li><li style=\"margin:2px 0;\">the Client fails to provide information or documents reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">the Client provides false, misleading or fraudulent information;</li><li style=\"margin:2px 0;\">the Client requests suspension; or</li><li style=\"margin:2px 0;\">continuation of the Services would be unlawful or impracticable.</li></ul><p style=\"margin:6px 0;\">Where practicable, Seventh Sky will notify the Client before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing thirty (30) days' written notice, provided all completed Services and outstanding payments have been settled.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">provides false or misleading ownership or property information;</li><li style=\"margin:2px 0;\">fails to make payment after receiving written notice;</li><li style=\"margin:2px 0;\">engages in unlawful or fraudulent conduct; or</li><li style=\"margin:2px 0;\">prevents Seventh Sky from performing the agreed Services.</li></ul><p style=\"margin:6px 0;\">Where the Client terminates after Services have commenced, the Client remains responsible for payment for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Services already completed;</li><li style=\"margin:2px 0;\">marketing and advertising costs incurred;</li><li style=\"margin:2px 0;\">buyer enquiries and inspections already coordinated;</li><li style=\"margin:2px 0;\">approved third-party costs incurred; and</li><li style=\"margin:2px 0;\">other reasonable expenses incurred before termination.</li></ul><p style=\"margin:6px 0;\">Termination does not affect any rights or obligations that arose before the termination date.</p>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Client acknowledges that Seventh Sky invests significant time, expertise and commercial resources in marketing the property, promoting the sale and introducing prospective buyers.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a prospective buyer to the Client, the Client agrees that, during the term of this Agreement and for twelve (12) months after the introduction, the Client will not intentionally bypass Seventh Sky to negotiate or complete the sale of the property directly with that introduced buyer without Seventh Sky's prior written consent.</p><p style=\"margin:6px 0;\">Where the property is sold to a buyer introduced by Seventh Sky during this period, the agreed professional fees or sales commission specified in the approved Quotation or Work Order shall remain payable.</p><p style=\"margin:6px 0;\">This clause does not prevent the Client from selling the property to a purchaser who was not introduced by Seventh Sky.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment must be made in writing and signed or electronically accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision does not waive its rights;</li><li style=\"margin:2px 0;\">if any provision is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, courier, registered post or email.</li></ul>"],
  ["GOVERNING LAW & DISPUTE RESOLUTION", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to make reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">If the dispute cannot be resolved through negotiation, the Parties may agree to mediation or another recognised alternative dispute resolution process before referring the matter to the competent courts of Bangladesh.</p><p style=\"margin:6px 0;\">Nothing in this clause prevents either Party from seeking urgent legal or equitable relief where necessary.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal, financial, taxation and professional advice;</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily; and</li><li style=\"margin:2px 0;\">agree to be legally bound by its terms.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, including through approved electronic signature platforms such as DocuSign. Each signed copy shall be deemed an original and together constitute one Agreement.</p>"],
];
